## Submitted testbench
```systemverilog
`timescale 1ns / 1ps
module tb;

  // Parameters
  localparam int CLK_PERIOD = 8;  // 125 MHz
  localparam logic [15:0] PRESCALE = 16'd5;
  localparam int BIT_CNT = PRESCALE * 8;  // cycles per bit

  // Clock and reset
  logic clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // Reset
  logic rst = 0;

  // UART Rx interface signals
  logic [7:0] m_axis_tdata;
  logic       m_axis_tvalid;
  logic       m_axis_tready;
  logic       busy;
  logic       overrun_error;
  logic       frame_error;
  logic [15:0] prescale;

  // UART Rx input
  logic rxd;

  // Tie off unused TX side signals
  logic [7:0] s_axis_tdata;
  logic       s_axis_tvalid;
  logic       s_axis_tready;

  // Instantiate uart_rx (the module under test)
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk(clk),
    .rst(rst),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .busy(busy),
    .overrun_error(overrun_error),
    .frame_error(frame_error),
    .prescale(prescale)
  );

  // Drive m_axis_tready always high
  initial begin
    m_axis_tready = 1'b1;
  end

  // Drive prescale value
  initial begin
    prescale = PRESCALE;
  end

  // -------------------------------------------------
  // Task to transmit a byte on rxd
  // -------------------------------------------------
  task automatic send_byte(input logic [7:0] data);
    integer bit_timer;
    integer bit_idx;
    begin
      // Wait for reset released
      wait (rst == 0);

      // Start bit
      rxd = 1'b0;
      bit_timer = 0;
      while (bit_timer < BIT_CNT) begin @(posedge clk); bit_timer++; end

      // Data bits, LSB first
      bit_idx = 0;
      while (bit_idx < 8) begin
        @(posedge clk);
        bit_timer = 0;
        while (bit_timer < BIT_CNT) begin @(posedge clk); bit_timer++; end
        rxd = data[bit_idx];
        bit_idx = bit_idx + 1;
      end

      // Stop bit
      @(posedge clk);
      bit_timer = 0;
      while (bit_timer < BIT_CNT) begin @(posedge clk); bit_timer++; end
      rxd = 1'b1;
    end
  endtask

  // -------------------------------------------------
  // Test stimulus
  // -------------------------------------------------
  initial begin
    // Reset pulse
    rst = 1'b0;
    #(CLK_PERIOD*2);
    rst = 1'b1;
    #(CLK_PERIOD*2);
    rst = 1'b0;
    #(CLK_PERIOD*2);

    // Send first byte 0x3C
    send_byte(8'h3C);
    // Send second byte 0xA5
    send_byte(8'hA5);

    // Give the design some time to finish
    #5000ns;
    $finish;
  end

endmodule
```

